import{_ as e,o,c as r,a4 as a}from"./chunks/framework.bruR1JhL.js";const u=JSON.parse('{"title":"AI enhancements","description":"Upscale pictures with AI, remove or replace backgrounds, and find and blur faces, all on your own PC.","frontmatter":{"title":"AI enhancements","description":"Upscale pictures with AI, remove or replace backgrounds, and find and blur faces, all on your own PC."},"headers":[],"relativePath":"docs/img-ai.md","filePath":"docs/img-ai.md","lastUpdated":1795509372000}'),s={name:"docs/img-ai.md"};function n(i,t,l,d,h,g){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="ai-enhancements" tabindex="-1">AI enhancements <a class="header-anchor" href="#ai-enhancements" aria-label="Permalink to &quot;AI enhancements&quot;">​</a></h1><p>These tools are under the <strong>AI</strong> tab in the <strong>Images</strong> section. Upscale Image and Remove background run AI models on your computer, and Blur face uses the face detector built into Windows. Your pictures are never uploaded.</p><p>All three work on one image at a time. They share the open image with Crop Image and the Photo editor, so a picture you open in one is open in the others. To open an image, drag it from the Explorer onto the tool, click <strong>Open image…</strong>, or select it in the Explorer and click the <strong>Use</strong> button with its name. Right-clicking an image in the Explorer also offers <strong>Upscale image</strong> and <strong>Remove background</strong>. See <a href="/tilepress/docs/interface">The Tilepress window</a> for the Explorer and the other general controls.</p><p>Each tool saves a new file and never changes the original. After saving, the <strong>Saved</strong> card offers <strong>Open</strong>, <strong>Show in folder</strong> and <strong>Keep editing this file</strong>, which opens the saved copy in the tool.</p><div class="tip custom-block"><p class="custom-block-title">Models are downloaded on first use</p><p>Upscale Image and Remove background each need a model file. Nothing is downloaded until you first use the tool, and the tool tells you beforehand what it will download. After that, it works offline. See <a href="/tilepress/docs/privacy">Privacy</a> for exactly what is downloaded and from where.</p></div><h2 id="upscale-image" tabindex="-1">Upscale Image <a class="header-anchor" href="#upscale-image" aria-label="Permalink to &quot;Upscale Image&quot;">​</a></h2><p>Upscale Image makes a picture two or four times larger with Real-ESRGAN, an AI super-resolution model. It rebuilds sharp detail instead of just stretching the pixels, which helps when a small or low-resolution picture has to be shown or printed bigger.</p><h3 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open an image.</li><li>Under <strong>Scale</strong>, choose <strong>2×</strong> or <strong>4×</strong>. Each card shows the size in pixels the result will have.</li><li>If you like, tick <strong>Extra sharpening</strong>, and choose the <strong>Format</strong> (and the <strong>Quality</strong> for JPG, WebP or AVIF).</li><li>Click <strong>Upscale 4× and save…</strong> (or <strong>Upscale 2× and save…</strong>) and choose where to save the file.</li><li>Wait while it works. The progress bar shows the model download the first time, then the tiles as they are processed.</li><li>When it&#39;s done, a before/after slider replaces the picture. Drag the divider to compare. Click <strong>2× zoom</strong>, <strong>3× zoom</strong> or <strong>4× zoom</strong> to magnify both sides, and move the pointer over the picture to look around. <strong>Fit</strong> shows the whole picture again.</li></ol><p>Under the button, a line tells you where the model ran: &quot;Ran on the GPU (DirectML).&quot; or &quot;Ran on the CPU.&quot;</p><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Scale</strong></td><td><strong>2×</strong> or <strong>4×</strong> the width and height.</td><td>4×</td></tr><tr><td><strong>Extra sharpening</strong></td><td>Sharpens the result a little more after upscaling.</td><td>Off</td></tr><tr><td><strong>Format</strong></td><td>PNG, JPG, WebP or AVIF.</td><td>PNG</td></tr><tr><td><strong>Quality</strong></td><td>10 to 100. Shown for JPG, WebP and AVIF only.</td><td>92</td></tr></tbody></table><h3 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li><strong>Inputs:</strong> JPG, PNG, WebP, HEIC/HEIF, AVIF, GIF, BMP, TIFF and ICO.</li><li><strong>Size limits:</strong> 4× takes pictures up to 4.2 megapixels, and 2× up to 16 megapixels, so the result stays around 64 megapixels at most. For a bigger picture, the tool says so and the button is disabled. Choose 2×, or make the picture smaller first with <a href="/tilepress/docs/img-layout">Crop Image</a> or <a href="/tilepress/docs/img-optimize">Resize Image</a>.</li><li><strong>File name:</strong> the suggested name is the original name plus <code>_x4</code> or <code>_x2</code>, next to the original, for example <code>holiday_x4.png</code>. If that file exists, a number is added, as in <code>holiday_x4 (2).png</code>.</li><li>The model always works at 4×. The 2× result is the 4× result reduced by half, which keeps the rebuilt detail.</li><li>The picture is processed in small overlapping tiles, so there are no seams between them.</li><li>Transparency is kept, but it&#39;s enlarged the ordinary way, not by the model. If you save a transparent picture as JPG, the transparent areas become white.</li><li>The saved file keeps the picture&#39;s metadata and colour profile. Its DPI is multiplied by the scale, so the printed size stays the same.</li><li><strong>Model:</strong> the first upscale downloads Real-ESRGAN General x4v3, about 4.5 MB (BSD-3-Clause licence, from Qualcomm AI Hub). It&#39;s checked against a checksum and kept for next time.</li><li><strong>Graphics card:</strong> the model runs on your graphics card through DirectML when it can. If there&#39;s no suitable graphics card, it runs on the processor, which is slower.</li></ul><h2 id="remove-background" tabindex="-1">Remove background <a class="header-anchor" href="#remove-background" aria-label="Permalink to &quot;Remove background&quot;">​</a></h2><p>Remove background finds the subject of a picture with ISNet, an AI segmentation model, and removes everything else. You can leave the background transparent, fill it with a colour, or replace it with a blurred copy of the picture.</p><h3 id="how-to-use-it-1" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-1" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open an image.</li><li>Click <strong>Remove the background</strong> under the picture. The first time, this downloads the model. Then the tool finds the subject (&quot;Finding the subject…&quot;).</li><li>Under <strong>Background</strong>, choose <strong>Transparent</strong>, <strong>Colour</strong> or <strong>Blurred</strong>.</li><li>Adjust the <strong>Edges</strong> if you need to. The preview updates as you change the options, without running the model again. A checkerboard shows the transparent areas.</li><li>To check the result, tick <strong>Compare with the original</strong> and drag the divider.</li><li>Choose the <strong>Format</strong> and click <strong>Save…</strong>.</li></ol><h3 id="options-1" tabindex="-1">Options <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Background</strong></td><td><strong>Transparent</strong>, <strong>Colour</strong> (a solid colour) or <strong>Blurred</strong> (a blurred copy of the picture).</td><td>Transparent</td></tr><tr><td>Colour swatches</td><td>With <strong>Colour</strong>: white, black, light grey, blue, green, red or yellow, or any colour from the colour picker.</td><td>White</td></tr><tr><td><strong>Blur</strong></td><td>With <strong>Blurred</strong>: 5 to 100. How blurred the background is.</td><td>50</td></tr><tr><td><strong>Clean-up</strong></td><td>0 to 90. Firms up soft, hazy edges. Higher values give a cleaner cut-out.</td><td>40</td></tr><tr><td><strong>Soften</strong></td><td>0 to 12 px, in half-pixel steps. Feathers the edge of the subject.</td><td>0 px</td></tr><tr><td><strong>Trim to the subject</strong></td><td>With <strong>Transparent</strong>: crops the result to the subject, with a small margin.</td><td>Off</td></tr><tr><td><strong>Compare with the original</strong></td><td>Shows a before/after slider. It appears once the preview is ready.</td><td>Off</td></tr><tr><td><strong>Format</strong></td><td>PNG, WebP or AVIF for a transparent background. JPG is also offered for <strong>Colour</strong> and <strong>Blurred</strong>.</td><td>PNG</td></tr></tbody></table><h3 id="good-to-know-1" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-1" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li><strong>Inputs:</strong> JPG, PNG, WebP, HEIC/HEIF, AVIF, GIF, BMP, TIFF and ICO.</li><li><strong>File name:</strong> the suggested name is the original name plus <code>_no_bg</code>, next to the original, for example <code>portrait_no_bg.png</code>.</li><li>The model runs once per picture. Changing the options afterwards reuses its result, so it&#39;s instant. While the app is open, Tilepress remembers the result for the last few pictures. If the file changes, the model runs again.</li><li>The model looks at the whole picture at once (at 1024 × 1024 pixels). The saved file is full size.</li><li>Areas that were already transparent in the original stay transparent.</li><li>The quality for JPG, WebP and AVIF is fixed at 92.</li><li>The saved file keeps the picture&#39;s metadata and colour profile.</li><li><strong>Model:</strong> the first use downloads ISNet (general use), about 179 MB (Apache-2.0 licence, from the rembg project&#39;s release on GitHub). It&#39;s checked against a checksum and kept for next time.</li><li><strong>Graphics card:</strong> like Upscale Image, it runs on your graphics card through DirectML when it can, otherwise on the processor.</li></ul><h2 id="blur-face" tabindex="-1">Blur face <a class="header-anchor" href="#blur-face" aria-label="Permalink to &quot;Blur face&quot;">​</a></h2><p>Blur face finds the faces in a photo and blurs, pixelates or covers them, for example before you share a picture of people who shouldn&#39;t be recognisable. You can check every box before saving, and add your own for anything else you want hidden.</p><h3 id="how-to-use-it-2" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-2" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open a photo. Tilepress looks for faces straight away (&quot;Looking for faces…&quot;) and puts a box on each face it finds. The picture shows the real result.</li><li>Check the boxes. Click a box to select it, then drag it to move it, or drag its handles to resize it. To remove the selected box, click <strong>Remove selected</strong> or press <kbd>Delete</kbd>.</li><li>To hide something it missed, click <strong>+ Add a box</strong>, then drag over the area on the photo. A single click adds a square box centred where you click.</li><li>Under <strong>Effect</strong>, choose <strong>Blur</strong>, <strong>Pixelate</strong> or <strong>Cover</strong>, and adjust the options.</li><li>Choose the <strong>Format</strong> and click <strong>Blur and save…</strong>.</li></ol><p>Untick <strong>Show boxes</strong> to see the result without the box outlines. <strong>Detect again</strong> discards your boxes and looks for faces again.</p><h3 id="options-2" tabindex="-1">Options <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Effect</strong></td><td><strong>Blur</strong>, <strong>Pixelate</strong>, or <strong>Cover</strong> with a solid colour.</td><td>Blur</td></tr><tr><td><strong>Strength</strong></td><td>With <strong>Blur</strong> and <strong>Pixelate</strong>: 10 to 100.</td><td>60</td></tr><tr><td><strong>Colour</strong></td><td>With <strong>Cover</strong>: the colour of the cover.</td><td>Black</td></tr><tr><td><strong>Grow boxes</strong></td><td>0 to 60%. Enlarges each box, because a face is usually a little bigger than the box the detector finds.</td><td>15%</td></tr><tr><td><strong>Oval</strong> / <strong>Rectangle</strong></td><td>The shape of the hidden area.</td><td>Oval</td></tr><tr><td><strong>Format</strong></td><td>Same as the original, JPG, PNG or WebP.</td><td>Same as the original</td></tr><tr><td><strong>Show boxes</strong></td><td>Shows or hides the box outlines on screen. It doesn&#39;t change the saved file.</td><td>On</td></tr></tbody></table><h3 id="good-to-know-2" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-2" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li><strong>Inputs:</strong> JPG, PNG, WebP, HEIC/HEIF, AVIF, GIF, BMP, TIFF and ICO. With <strong>Same as the original</strong>, HEIC photos are saved as JPG and ICO files as PNG.</li><li><strong>File name:</strong> the suggested name is the original name plus <code>_blurred</code>, next to the original, for example <code>team_blurred.jpg</code>.</li><li>Faces are found with the face detector built into Windows, so there&#39;s nothing to download. Large photos are checked at 2048 pixels and then also in full-resolution tiles, so small faces in group photos are found too.</li><li>The detector can miss faces, so look over the whole photo before you save. <strong>Blur and save…</strong> stays disabled until there is at least one box.</li><li>Blur and pixelate fade out softly at the edge of each box. Cover has a hard edge.</li><li>The saved copy leaves out the photo&#39;s metadata, such as the camera and the location, and its colour profile. There&#39;s no option to keep them.</li><li>The quality for JPG and WebP is fixed at 92.</li></ul>',31)])])}const p=e(s,[["render",n]]);export{u as __pageData,p as default};
